// ======================================================================
// HELPERS de fecha (timezone Argentina)
// ======================================================================
function fmtArgentina(d) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Argentina/Buenos_Aires',
    year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(d);
  const y = parts.find(p => p.type === 'year').value;
  const m = parts.find(p => p.type === 'month').value;
  const dd = parts.find(p => p.type === 'day').value;
  return `${y}-${m}-${dd}`;
}

function addDays(yyyy_mm_dd, n) {
  const [y, m, d] = yyyy_mm_dd.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  date.setUTCDate(date.getUTCDate() + n);
  const yy = date.getUTCFullYear();
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

function hoyArgentina() {
  return fmtArgentina(new Date());
}

// ======================================================================
// INPUT
//
// C-27: este nodo ya NO usa $getWorkflowStaticData. En n8n 2.4.4 ese store
// no sobrevive entre ejecuciones (verificado sobre ejecuciones reales), y
// cada mensaje de Telegram es una ejecucion distinta. El estado de la
// conversacion vive en Postgres y llega por HTTP - GET Captura Pendiente,
// que corre justo antes que este nodo.
//
// Como el nodo HTTP reemplaza el item, el input original del orquestador se
// lee del trigger por nombre -- el mismo patron que ya usaban
// Code - Verificar Slots y Code - Extraer Turno ID para el chat_id.
// ======================================================================
let trigger = {};
try {
  trigger = $('Execute Workflow Trigger').first().json || {};
} catch (e) {}

const chatId = trigger.chat_id;
const comando = trigger.comando || 'crear';
const textRaw = String(trigger.text || '');
const payload = trigger.payload || {};

// Resultado del GET: 200 = hay una captura pendiente, 404 = no hay.
// neverError + fullResponse son obligatorios en ese nodo; sin ellos el 404
// tira excepcion y este nodo nunca corre.
const httpIn = ($input.all()[0] && $input.all()[0].json) || {};
const capturaBody = httpIn.body || {};
const hayCaptura = httpIn.statusCode === 200 && !!capturaBody.turno_id;

// Un comando reconocido gana sobre una captura pendiente (escape hatch):
// quien abandona una reserva a mitad de pregunta no debe quedar atrapado.
const freshStart = payload.fresh_start === true;

// ======================================================================
// CAPTURA EN CURSO: si hay una captura viva y el orquestador adjunto un
// texto libre, esta ejecucion responde una pregunta de identidad. Se corta
// aca el resto de la logica de creacion -- no tiene sentido calcular
// fecha/slot para un DNI. Esto es lo que hace que un "15" mientras el bot
// espera un DNI sea un DNI invalido y no el slot numero 15: el desempate
// ocurre aca, con la base a la vista, no en el orquestador.
// ======================================================================
if (hayCaptura && !freshStart && payload.respuesta_captura !== undefined) {
  return [{
    json: {
      chat_id: chatId,
      comando: comando,
      accion: 'captura',
      respuesta_captura: String(payload.respuesta_captura),
      captura_turno_id: capturaBody.turno_id,
      captura_paso: capturaBody.paso,
      captura_datos: capturaBody.datos || {},
      fecha: '',
      slot: '',
      rango: '',
      fecha_inicio: '',
      mensaje_error: ''
    }
  }];
}

let fecha = payload.fecha || '';
let slot = payload.slot || '';
let rango = payload.rango || '';
let fechaRaw = payload.fecha_raw || '';
let accion = '';
let mensajeError = '';

// Defensa: parsear callbacks de slot (formato HH:MM:f:YYYY-MM-DD). La fecha
// viaja en el callback a proposito: es la unica forma de que sobreviva entre
// ejecuciones sin tocar la base.
if (textRaw.startsWith('cmd:crear:slot:')) {
  const parsed = textRaw.substring('cmd:crear:slot:'.length);
  if (parsed !== 'none') {
    const fIdx = parsed.indexOf(':f:');
    if (fIdx >= 0) {
      slot = parsed.substring(0, fIdx);
      if (!fecha) fecha = parsed.substring(fIdx + 3);
    } else {
      slot = parsed;
    }
  }
}

// ======================================================================
// CALCULO DE FECHA
// ======================================================================
if (!fecha && rango && rango !== 'exacto') {
  let daysToAdd = 0;
  if (rango === 'inmediato') daysToAdd = 1;
  else if (rango === '2semanas') daysToAdd = 14;
  else if (rango === '1mes') daysToAdd = 28;
  if (daysToAdd > 0) {
    fecha = addDays(hoyArgentina(), daysToAdd);
  }
}

if (!fecha && fechaRaw) {
  const match = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(fechaRaw);
  if (match) {
    const day = parseInt(match[1], 10);
    const month = parseInt(match[2], 10) - 1;
    const year = parseInt(match[3], 10);
    const parsed = new Date(year, month, day);
    if (parsed.getDate() === day && parsed.getMonth() === month && parsed.getFullYear() === year) {
      const todayStr = hoyArgentina();
      const maxStr = addDays(todayStr, 90);
      const iso = String(year) + '-' + String(month + 1).padStart(2, '0') + '-' + String(day).padStart(2, '0');
      if (iso < todayStr) {
        accion = 'fecha_invalida';
        mensajeError = 'La fecha está en el pasado.';
      } else if (iso > maxStr) {
        accion = 'fecha_invalida';
        mensajeError = 'Solo podés reservar hasta 3 meses adelante.';
      } else {
        fecha = iso;
      }
    } else {
      accion = 'fecha_invalida';
      mensajeError = 'La fecha no es válida (día o mes incorrecto).';
    }
  } else {
    accion = 'fecha_invalida';
    mensajeError = 'Formato incorrecto. Usá DD/MM/AAAA (ej: 15/07/2026).';
  }
}

// ======================================================================
// TEXTO LIBRE SIN NADA QUE HACER: ni captura viva, ni fecha, ni slot, ni
// rango. Es el "hola" de alguien que no esta reservando. Se marca 'ayuda'
// -- que no matchea ninguna regla de Switch Accion y cae por el fallback a
// Code - Retorno Estado -- para que el UNICO mensaje sea el menu de ayuda
// del orquestador. Sin esto el flujo mandaba "para cuando necesitas el
// turno?" Y el menu de ayuda, dos mensajes por un solo "hola".
// ======================================================================
if (!accion && payload.respuesta_captura !== undefined && !freshStart &&
    !fecha && !slot && !rango && !fechaRaw) {
  accion = 'ayuda';
}

// ======================================================================
// DECIDIR ACCION FINAL
// ======================================================================
if (!accion) {
  if (rango === 'exacto' && !fecha) {
    accion = 'pedir_fecha';
  } else if (fecha && slot) {
    accion = 'crear_turno';
  } else if (fecha) {
    accion = 'pedir_slot';
  } else {
    accion = 'pedir_rango';
  }
}

return [{
  json: {
    chat_id: chatId,
    comando: comando,
    accion: accion,
    fecha: fecha,
    slot: slot,
    rango: rango,
    fecha_inicio: fecha || '',
    mensaje_error: mensajeError
  }
}];

// ======================================================================
// HELPERS
// ======================================================================
function addDays(yyyy_mm_dd, n) {
  const [y, m, d] = yyyy_mm_dd.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  date.setUTCDate(date.getUTCDate() + n);
  const yy = date.getUTCFullYear();
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

// ======================================================================
// LEER SLOTS DEL HTTP RESPONSE
// ======================================================================
const items = $input.all();
let slots = [];

if (items.length > 0) {
  if (Array.isArray(items[0].json)) {
    slots = items[0].json;
  } else {
    slots = items.map(item => item.json);
  }
}
slots = slots.filter(function (s) { return s && typeof s.hora_inicio === "string" && s.disponible !== false; });

// chatId y fecha_inicio los leemos del Code - Decidir Paso (sobrevive al loop)
let chatId = '';
let fechaInicial = '';
let fechaInicio = '';
try {
  const codeData = $('Code - Decidir Paso').first().json;
  if (codeData) {
    chatId = codeData.chat_id || '';
    fechaInicial = codeData.fecha || '';
    fechaInicio = codeData.fecha_inicio || fechaInicial;
  }
} catch (e) {
  // fallback silencioso
}

// ======================================================================
// STATIC DATA: fecha REAL consultada (avanza con cada retry) + contador
// ======================================================================
const staticData = $getWorkflowStaticData('global');
const contadorKey = 'contador_' + chatId;
const fechaKey = 'fecha_' + chatId;
const ctxKey = chatId ? 'ctx_' + chatId : null;
let contador = staticData[contadorKey] || 0;
const fechaActual = staticData[fechaKey] || fechaInicial;

if (slots.length > 0) {
  // Guardar slots en staticData para resolver slot_numero después
  if (ctxKey) {
    const existing = staticData[ctxKey] || {};
    existing.slots = slots;
    staticData[ctxKey] = existing;
  }
  delete staticData[contadorKey];
  delete staticData[fechaKey];
  return [{
    json: {
      chat_id: chatId,
      fecha: fechaActual,
      fecha_inicio: fechaInicio,
      slots: slots,
      decision: 'found'
    }
  }];
}

// No hay slots. ¿Ya intentamos los 7 días?
const MAX_DIAS = 7;
if (contador >= MAX_DIAS - 1 || !fechaActual) {
  delete staticData[contadorKey];
  delete staticData[fechaKey];
  return [{
    json: {
      chat_id: chatId,
      fecha: fechaActual,
      fecha_inicio: fechaInicio,
      slots: [],
      decision: 'exhausted'
    }
  }];
}

// Retry: +1 día desde la fecha realmente consultada
staticData[contadorKey] = contador + 1;
const nextFecha = addDays(fechaActual, 1);
staticData[fechaKey] = nextFecha;
return [{
  json: {
    chat_id: chatId,
    fecha: nextFecha,
    fecha_inicio: fechaInicio,
    slots: [],
    decision: 'retry'
  }
}];

const input = ($input.all()[0] && $input.all()[0].json) || {};
const chatId = input.chat_id;
const fecha = input.fecha || '';
let slots = input.slots || [];
if (!Array.isArray(slots)) slots = [];
const disponibles = slots.filter(function (s) { return s.disponible !== false; });

// Un boton por slot (una fila cada uno). La FECHA viaja en el callback_data
// para que la seleccion sea STATELESS: no depende de $getWorkflowStaticData.
// Formato: cmd:crear:slot:HH:MM:f:YYYY-MM-DD  (<64 bytes, limite de Telegram)
const inlineKeyboard = disponibles.map(function (s) {
  return [{
    text: s.hora_inicio + (s.hora_fin ? ' - ' + s.hora_fin : ''),
    callback_data: 'cmd:crear:slot:' + s.hora_inicio + ':f:' + fecha
  }];
});

const texto = '\uD83D\uDD50 Horarios disponibles para el ' + fecha + ':\n\nElegi un horario \uD83D\uDC47';

// tg_body = payload listo para POST /sendMessage (lo envia el nodo HTTP siguiente)
return [{
  json: {
    chat_id: chatId,
    fecha: fecha,
    slots: disponibles,
    cantidad: disponibles.length,
    tg_body: {
      chat_id: chatId,
      text: texto,
      reply_markup: { inline_keyboard: inlineKeyboard }
    }
  }
}];

// Leer chat_id del Code - Decidir Paso (sobrevive al flow)
let chatId = '';
try {
  const codeData = $('Code - Decidir Paso').first().json;
  if (codeData) {
    chatId = codeData.chat_id || '';
  }
} catch (e) {}

// fullResponse: true es obligatorio -- sin eso un 4xx tira excepcion antes
// de llegar aca y el chequeo de statusCode de abajo seria codigo muerto.
const input = ($input.all()[0] && $input.all()[0].json) || {};
const statusCode = input.statusCode;
const body = input.body || {};
const fecha = body.fecha;
const slot = body.hora_inicio;
const turnoId = body.id;
const errorStatus = typeof statusCode === 'number' && statusCode >= 400;
const errorDetail = body.detail || (errorStatus ? 'Error HTTP ' + statusCode : null);
const exito = !!turnoId && !errorStatus;

// C-27: no se escribe ningun estado aca. La reserva creada por POST /turnos
// YA es el estado de la captura -- reserva_temporal nace con datos_captura
// vacio, y un datos_captura vacio significa "falta el DNI". El chat se
// resuelve a este turno por el TurnoDestinatario canal TELEGRAM que el
// backend escribe con el telegram_chat_id que le mandamos.
return [{
  json: {
    chat_id: chatId,
    fecha: fecha,
    slot: slot,
    turno_id: turnoId,
    exito: exito,
    error: errorDetail
  }
}];

// Procesa la respuesta del usuario segun el paso pendiente.
//
// C-27: el paso y los datos ya capturados NO se leen de staticData -- llegan
// desde Postgres via HTTP - GET Captura Pendiente y los propaga
// Code - Decidir Paso. Este nodo solo VALIDA e interpreta el texto; quien
// persiste es HTTP - PATCH Captura (o directamente el PUT de confirmacion
// cuando ya no queda nada por preguntar).
const input = ($input.all()[0] && $input.all()[0].json) || {};
const chatId = input.chat_id;
const respuesta = String(input.respuesta_captura || '').trim();
const turnoId = input.captura_turno_id;
const paso = input.captura_paso;
const datos = Object.assign({}, input.captura_datos || {});

let decision;
let datosNuevos = {};

if (paso === 'dni') {
  // DNI argentino: 7 u 8 digitos, sin puntos ni guiones (spec: "A malformed
  // DNI is rejected without losing the reservation" -- por eso no se
  // persiste nada en esta rama).
  if (!/^\d{7,8}$/.test(respuesta)) {
    decision = 'dni_invalido';
  } else {
    datos.dni = respuesta;
    datosNuevos = { dni: respuesta };
    decision = 'buscar';
  }
} else if (paso === 'nombre') {
  // D5: nombre y apellido en un solo mensaje.
  const partes = respuesta.split(/\s+/).filter(Boolean);
  datos.nombre = partes[0] || respuesta;
  datos.apellido = partes.slice(1).join(' ') || datos.nombre;
  datosNuevos = { nombre: datos.nombre, apellido: datos.apellido };
  decision = 'guardar';
} else if (paso === 'telefono') {
  // D5: telefono y email (opcional) en un solo mensaje. Es la ultima
  // pregunta: con esto se puede confirmar sin pasar por el PATCH, porque no
  // hay un mensaje siguiente que necesite recordar nada.
  const partes = respuesta.split(/[\s,]+/).filter(Boolean);
  datos.telefono = (partes[0] || '').replace(/\D/g, '');
  const posibleEmail = partes.slice(1).join(' ');
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(posibleEmail)) {
    datos.email = posibleEmail;
  }
  decision = 'confirmar';
} else if (paso === 'confirmar') {
  decision = 'confirmar';
} else {
  decision = 'sin_match';
}

return [{
  json: {
    chat_id: chatId,
    turno_id: turnoId,
    decision: decision,
    datos_nuevos: datosNuevos,
    dni: datos.dni || '',
    nombre: datos.nombre || '',
    apellido: datos.apellido || '',
    telefono: datos.telefono || '',
    email: datos.email || ''
  }
}];

// Branch de la busqueda de paciente (design § D1, task 7.3): 200 = paciente
// existente, 404 = paciente nuevo. neverError + fullResponse en
// HTTP - GET Buscar Paciente son obligatorios -- sin ellos el 404 tira
// excepcion y este nodo nunca corre.
let previo = {};
try {
  previo = $('Code - Procesar Captura').first().json || {};
} catch (e) {}

const input = ($input.all()[0] && $input.all()[0].json) || {};
const statusCode = input.statusCode;
const body = input.body || {};

if (statusCode === 200) {
  // Paciente existente (spec "Returning patient"): se completan los datos
  // guardados SIN volver a pedirselos. Se va derecho a confirmar, asi que
  // tampoco hace falta persistirlos: el PUT los lleva en el mismo salto.
  return [{
    json: {
      chat_id: previo.chat_id,
      turno_id: previo.turno_id,
      encontrado: true,
      dni: previo.dni,
      nombre: body.nombre,
      apellido: body.apellido,
      telefono: body.telefono,
      email: previo.email || ''
    }
  }];
}

// Paciente nuevo: hay que preguntar nombre, o sea que HAY un mensaje
// siguiente -- el DNI recien capturado debe persistirse antes de preguntar.
return [{
  json: {
    chat_id: previo.chat_id,
    turno_id: previo.turno_id,
    encontrado: false,
    datos_nuevos: { dni: previo.dni },
    dni: previo.dni,
    nombre: '',
    apellido: '',
    telefono: '',
    email: ''
  }
}];

// Lee el resultado de HTTP - PUT Confirmar Turno. neverError + fullResponse
// (design § D6) son obligatorios: sin esas opciones un 409 tira excepcion y
// las ramas de expirado / paciente con turno activo son inalcanzables.
let chatId = null;
try {
  chatId = $('Code - Decidir Paso').first().json.chat_id;
} catch (e) {}

// C-27: el nombre del paciente ya NO se lee de staticData. El PUT se
// alimenta de dos ramas -- paciente encontrado (Code - Evaluar Paciente) o
// datos recien capturados (Code - Procesar Captura) -- y se toma el nombre
// de la que efectivamente corrio. No hace falta limpiar nada: el backend
// borra reserva_temporal al confirmar, y con ella los datos de la captura.
let datos = {};
try {
  datos = $('Code - Evaluar Paciente').first().json || {};
} catch (e) {}
if (!datos.nombre) {
  try {
    datos = $('Code - Procesar Captura').first().json || {};
  } catch (e) {}
}

const input = ($input.all()[0] && $input.all()[0].json) || {};
const statusCode = input.statusCode;
const body = input.body || {};
const detail = String(body.detail || '').toLowerCase();

let decision = 'error';
if (typeof statusCode === 'number' && statusCode >= 200 && statusCode < 300) {
  decision = 'confirmado';
} else if (statusCode === 409 && detail.includes('expir')) {
  decision = 'expirado';
} else if (statusCode === 409 && detail.includes('turno activo')) {
  decision = 'paciente_turno_activo';
}

return [{
  json: {
    chat_id: chatId,
    decision: decision,
    nombre: datos.nombre || '',
    apellido: datos.apellido || '',
    fecha: body.fecha || '',
    hora: body.hora_inicio || ''
  }
}];

parameters.text:
=✅ Turno confirmado para {{ $json.nombre }} {{ $json.apellido }}.

📅 Fecha: {{ $json.fecha }}
🕐 Hora: {{ $json.hora }}

Te vamos a recordar por Telegram antes del turno.

