// Fan-in de TODAS las ramas terminales del sub-flujo (task 7.0).
//
// C-27: lo unico que el orquestador necesita saber ya no es si hay una
// captura pendiente -- eso lo consulta el sub-flujo contra la base en cada
// mensaje. Queda solo mostrar_ayuda, porque el menu de ayuda vive en el
// orquestador y este workflow no puede mandarlo por su cuenta.
let chatId = null;
let accion = '';
try {
  const decidido = $('Code - Decidir Paso').first().json || {};
  chatId = decidido.chat_id;
  accion = decidido.accion || '';
} catch (e) {}

// 'ayuda' es el UNICO caso que pide el menu: texto libre sin captura viva y
// sin nada que reservar. Cualquier otra accion ya mando su propio mensaje,
// asi que pedir ayuda ademas produciria dos respuestas a un solo mensaje.
const mostrarAyuda = accion === 'ayuda';

return [{
  json: {
    chat_id: chatId,
    mostrar_ayuda: mostrarAyuda
  }
}];

// Lee la respuesta del PATCH y decide que pregunta sigue.
//
// El backend deriva el paso de los datos guardados y lo devuelve, asi que
// el flujo no necesita llevar la cuenta: pregunta lo que el backend dice
// que falta. Un paso que contradiga los datos no es representable.
let chatId = null;
try {
  chatId = $('Code - Decidir Paso').first().json.chat_id;
} catch (e) {}

const input = ($input.all()[0] && $input.all()[0].json) || {};
const body = input.body || {};

return [{
  json: {
    chat_id: chatId,
    paso: body.paso || '',
    turno_id: body.turno_id || null
  }
}];
